                WHERE time >= NOW() - INTERVAL '7 days'
                GROUP BY day
            )
        `;
    break;

    case 5: // pass duration
        msg.query = `
            SELECT
            AVG(duration) / 60 AS avg_pass_duration_min
                FROM passes
                WHERE time >= NOW() - INTERVAL '7 days'
        `;
    break;

    case 6: // max elevation
        msg.query = `
            SELECT
                AVG(max_el) AS avg_max_elevation_deg
            FROM passes
            WHERE time >= NOW() - INTERVAL '7 days'
        `;
    break;

    case 7: // pass gap
        msg.query = `
            SELECT
                AVG(gap_seconds) / 60 AS avg_pass_gap_min
            FROM (
                SELECT
                    EXTRACT(EPOCH FROM (
                        time - LAG(time) OVER (PARTITION BY sat ORDER BY time)
                    )) AS gap_seconds
                FROM passes
                WHERE time >= NOW() - INTERVAL '7 days'
            )
            WHERE gap_seconds IS NOT NULL
        `;
    break;



    // =================
