// WGS84 constants in km
const a = 6378.137; 
const e2 = 6.69437999014e-3;

// Convert degrees to radians
function deg2rad(deg)
{
    return deg * Math.PI / 180;
}

// LLA → ECEF (km)
function llaToEcef(lat, lon, alt)
{
    let phi = deg2rad(lat);
    let lambda = deg2rad(lon);

    let N = a / Math.sqrt(1 - e2 * Math.sin(phi) * Math.sin(phi));

    let x = (N + alt) * Math.cos(phi) * Math.cos(lambda);
    let y = (N + alt) * Math.cos(phi) * Math.sin(lambda);
    let z = (N * (1 - e2) + alt) * Math.sin(phi);

    return { x, y, z };
}

